const meals=['Breakfast','Lunch','Dinner','Snacks'];
const profileDefault={age:22,sex:'male',feet:6,inches:0,weight:150,goalWeight:165,activity:1.725,goal:125,calculated:false};
const seed={account:{created:false,name:''},calorieGoal:2400,macros:{protein:190,carbs:250,fat:70},profile:profileDefault,diary:[],recent:[],favorites:[],saved:[],weights:[],water:{}};
let state=load(),selectedMeal='Snacks',selectedDate=today(),pendingFood=null,editingEntryId=null,removeId=null,scanner=null,scanning=false,currentFoodTab='recent';
state={...seed,...state,account:{...seed.account,...(state.account||{})},profile:{...profileDefault,...(state.profile||{})},macros:{...seed.macros,...(state.macros||{})},water:state.water||{}};
const migratedGoalRate=!state.goalRateVersion;
if(migratedGoalRate){if(state.profile.goal===250)state.profile.goal=125;else if(state.profile.goal===400)state.profile.goal=250;state.goalRateVersion=2}
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function load(){try{return JSON.parse(localStorage.getItem('bitelog-v1')||'{}')}catch{return {}}}
function save(){try{localStorage.setItem('bitelog-v1',JSON.stringify(state))}catch{toast('Could not save—download a backup now')}}
function localDate(d=new Date()){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
function today(){return localDate()}
function shiftDate(date,days){const d=new Date(`${date}T12:00:00`);d.setDate(d.getDate()+days);return localDate(d)}
function id(){return `${Date.now()}-${Math.random().toString(36).slice(2)}`}
function n(v){const x=Number(v);return Number.isFinite(x)?x:0}
function round(x){return Math.round(x*10)/10}
function esc(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function sum(items){return items.reduce((a,x)=>{const q=n(x.servings)||1;a.calories+=n(x.calories)*q;a.protein+=n(x.protein)*q;a.carbs+=n(x.carbs)*q;a.fat+=n(x.fat)*q;return a},{calories:0,protein:0,carbs:0,fat:0})}
function normalizeProduct(p){const nut=p.nutriments||{},quantity=n(p.serving_quantity)||100,m=quantity/100,hasServing=nut['energy-kcal_serving']!=null||nut.proteins_serving!=null||nut.carbohydrates_serving!=null||nut.fat_serving!=null;const value=(servingKey,hundredKey)=>hasServing?n(nut[servingKey]):n(nut[hundredKey])*m;return{id:p.code?`barcode-${p.code}`:id(),barcode:p.code||'',name:p.product_name||p.generic_name||'Food',brand:p.brands||'',serving:p.serving_size||(quantity!==100?`${quantity} g`:'100 g'),calories:Math.round(value('energy-kcal_serving','energy-kcal_100g')),protein:round(value('proteins_serving','proteins_100g')),carbs:round(value('carbohydrates_serving','carbohydrates_100g')),fat:round(value('fat_serving','fat_100g')),source:'Open Food Facts'}}
function isFavorite(food){return state.favorites.some(x=>x.id===food.id||food.barcode&&x.barcode===food.barcode)}
function foodRow(f,attrs='',buttons=''){const q=n(f.servings)||1;return `<div class="food-row" ${attrs}><div class="food-copy"><b>${esc(f.name)}</b><small>${f.brand?esc(f.brand)+' · ':''}${esc(f.serving||'1 serving')}${q!==1?` · ${round(q)} servings`:''}</small></div><div class="food-numbers"><b>${Math.round(n(f.calories)*q)} cal</b><small>P ${round(n(f.protein)*q)} · C ${round(n(f.carbs)*q)} · F ${round(n(f.fat)*q)}</small></div>${buttons}</div>`}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2200)}
function showView(name){const btn=$(`.nav-btn[data-view="${name}"]`);$$('.nav-btn').forEach(x=>x.classList.toggle('active',x===btn));$$('.view').forEach(v=>v.classList.toggle('active',v.id===`${name}-view`));window.scrollTo({top:0,behavior:'smooth'})}
function render(){renderDiary();renderFoodList();renderSaved();renderWeight();renderGoals();save()}

function renderDiary(){const items=state.diary.filter(x=>x.date===selectedDate),t=sum(items),left=state.calorieGoal-t.calories,current=today(),tomorrow=shiftDate(current,1),isToday=selectedDate===current,isTomorrow=selectedDate===tomorrow,isPast=selectedDate<current;$('#remaining').textContent=Math.round(left).toLocaleString();$('#goal-cal').textContent=state.calorieGoal.toLocaleString();$('#food-cal').textContent=Math.round(t.calories).toLocaleString();$('#left-cal').textContent=Math.round(left).toLocaleString();$('#today-label').textContent=isToday?'TODAY':isTomorrow?'TOMORROW':new Date(`${selectedDate}T12:00:00`).toLocaleDateString(undefined,{weekday:'long',month:'short',day:'numeric'}).toUpperCase();$('#next-day').disabled=isTomorrow;$('#next-day').style.opacity=isTomorrow?'.35':'1';$('#target-prompt').hidden=state.profile.calculated;$('#water-count').textContent=state.water[selectedDate]||0;const defs=[['Protein','protein','#178059'],['Carbs','carbs','#da7a2d'],['Fat','fat','#7459bd']];$('#macro-grid').innerHTML=defs.map(([label,key,color])=>{const goal=state.macros[key],value=t[key],pct=Math.min(100,value/goal*100||0);return `<article class="macro-card"><small>${label}</small><strong>${Math.round(value)}g</strong><div class="bar"><i style="width:${pct}%;background:${color}"></i></div><em>of ${goal}g</em></article>`}).join('');$('#meal-list').innerHTML=meals.map(meal=>{const foods=items.filter(x=>x.meal===meal);return `<article class="meal-card"><div class="meal-head"><h2>${meal}</h2><div class="meal-tools"><span>${Math.round(sum(foods).calories)} cal</span>${foods.length&&isPast?`<button class="copy-meal" data-copy-meal="${meal}">Copy to today</button>`:''}</div></div>${foods.map(f=>foodRow(f,`data-entry="${f.entryId}"`)).join('')}<button class="add-btn" data-meal="${meal}">＋ Add food</button></article>`}).join('');$$('[data-meal]').forEach(b=>b.onclick=()=>openAdd(b.dataset.meal));$$('[data-entry]').forEach(r=>r.onclick=()=>openEntry(state.diary.find(x=>x.entryId===r.dataset.entry),true));$$('[data-copy-meal]').forEach(b=>b.onclick=()=>copyMeal(b.dataset.copyMeal))}
function copyMeal(meal){const source=state.diary.filter(x=>x.date===selectedDate&&x.meal===meal);if(!source.length)return;source.forEach(x=>state.diary.push({...x,entryId:id(),date:today()}));selectedDate=today();toast(`${meal} copied to today`);render()}
function openAdd(meal){selectedMeal=meal;$('#add-title').textContent=meal;$('#food-search').value='';$('#search-results').innerHTML='';$('#search-status').textContent='';$('#add-dialog').showModal()}

async function searchFoods(){const q=$('#food-search').value.trim();if(q.length<2)return toast('Type at least 2 letters');$('#search-button').disabled=true;$('#search-status').textContent='Searching…';$('#search-results').innerHTML='';try{const url=`https://world.openfoodfacts.org/cgi/search.pl?search_terms=${encodeURIComponent(q)}&search_simple=1&action=process&json=1&page_size=15`;const res=await fetch(url);if(!res.ok)throw new Error(`HTTP ${res.status}`);const body=await res.json(),foods=(body.products||[]).map(normalizeProduct).filter(f=>f.name!=='Food'&&f.calories>0);$('#search-status').textContent=foods.length?`${foods.length} community database results`:'No foods found';$('#search-results').innerHTML=foods.map((f,i)=>foodRow(f,'',`<button class="result-add" data-result="${i}">Add</button>`)).join('');$$('[data-result]').forEach(b=>b.onclick=()=>openEntry(foods[n(b.dataset.result)],false))}catch{$('#search-status').textContent='Search unavailable or rate-limited. Try scanning or manual entry.'}finally{$('#search-button').disabled=false}}
function renderFoodList(){const foods=currentFoodTab==='favorites'?state.favorites:state.recent;$('#recent-list').innerHTML=foods.length?foods.map(f=>foodRow(f,`data-quick="${f.id}"`,`<button class="star-btn" data-star="${f.id}" aria-label="Favorite">${isFavorite(f)?'★':'☆'}</button>`)).join(''):`<p class="empty">No ${currentFoodTab} foods yet.</p>`;$$('[data-quick]').forEach(r=>r.onclick=e=>{if(e.target.closest('[data-star]'))return;const list=currentFoodTab==='favorites'?state.favorites:state.recent,food=list.find(x=>x.id===r.dataset.quick);if(food)openEntry(food,false)});$$('[data-star]').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleFavorite((currentFoodTab==='favorites'?state.favorites:state.recent).find(x=>x.id===b.dataset.star))})}
function toggleFavorite(food){if(!food)return;if(isFavorite(food)){state.favorites=state.favorites.filter(x=>x.id!==food.id);toast('Removed from favorites')}else{state.favorites.unshift({...food});toast('Saved as favorite')}renderFoodList();save()}

function openEntry(food,editing=false){pendingFood={...food};editingEntryId=editing?food.entryId:null;selectedMeal=food.meal||selectedMeal;$('#entry-food-name').textContent=food.name;$('#entry-servings').value=food.servings||1;$('#entry-meal').value=selectedMeal;$('#entry-favorite').checked=isFavorite(food);$('#delete-entry').hidden=!editing;$('#entry-source-note').textContent=food.source==='Open Food Facts'?'Community data from Open Food Facts—verify serving size and nutrition against the package label.':'Manually entered nutrition.';updateEntryPreview();if($('#add-dialog').open)$('#add-dialog').close();$('#entry-dialog').showModal()}
function updateEntryPreview(){if(!pendingFood)return;const q=Math.max(.1,n($('#entry-servings').value)||1);$('#entry-preview').textContent=`${Math.round(pendingFood.calories*q)} calories · ${round(pendingFood.protein*q)}g protein · ${round(pendingFood.carbs*q)}g carbs · ${round(pendingFood.fat*q)}g fat`}
function saveEntry(e){e.preventDefault();if(!pendingFood)return;const servings=Math.max(.1,n($('#entry-servings').value)||1),meal=$('#entry-meal').value,base={...pendingFood,servings};delete base.entryId;delete base.date;delete base.meal;if(editingEntryId){const i=state.diary.findIndex(x=>x.entryId===editingEntryId);if(i>=0)state.diary[i]={...state.diary[i],...base,servings,meal}}else{state.diary.push({...base,entryId:id(),meal,date:selectedDate,servings})}state.recent=[base,...state.recent.filter(x=>x.id!==base.id)].slice(0,30);if($('#entry-favorite').checked&&!isFavorite(base))state.favorites.unshift({...base});if(!$('#entry-favorite').checked&&isFavorite(base))state.favorites=state.favorites.filter(x=>x.id!==base.id);$('#entry-dialog').close();toast(editingEntryId?'Food updated':'Food added');editingEntryId=null;render()}
function deleteEntry(){if(!editingEntryId)return;state.diary=state.diary.filter(x=>x.entryId!==editingEntryId);$('#entry-dialog').close();editingEntryId=null;toast('Food removed');render()}

function addManual(e){e.preventDefault();const f=new FormData(e.target),food={id:id(),name:f.get('name').trim(),brand:f.get('brand').trim(),serving:f.get('serving').trim(),calories:n(f.get('calories')),protein:n(f.get('protein')),carbs:n(f.get('carbs')),fat:n(f.get('fat'))};e.target.reset();e.target.elements.serving.value='1 serving';$('#food-dialog').close();openEntry(food,false)}
async function openScanner(){if(!window.Html5Qrcode){toast('Scanner is loading—try again');return}$('#add-dialog').close();$('#scanner-dialog').showModal();$('#scan-status').textContent='Center the barcode inside the box';scanning=true;scanner=new Html5Qrcode('reader');try{await scanner.start({facingMode:'environment'},{fps:10,qrbox:{width:280,height:160},aspectRatio:1.2},code=>foundBarcode(code),()=>{})}catch{scanning=false;$('#scan-status').textContent='Camera unavailable. Check Safari camera permission.'}}
async function foundBarcode(code){if(!scanning)return;scanning=false;$('#scan-status').textContent='Finding food…';await stopScanner();try{const res=await fetch(`https://world.openfoodfacts.org/api/v2/product/${encodeURIComponent(code)}.json`);if(!res.ok)throw new Error();const body=await res.json();if(body.status!==1||!body.product)throw new Error();$('#scanner-dialog').close();openEntry(normalizeProduct({...body.product,code}),false)}catch{$('#scanner-dialog').close();$('#food-dialog').showModal();toast('Food not found—enter the label')}}
async function stopScanner(){if(scanner){try{if(scanner.isScanning)await scanner.stop();await scanner.clear()}catch{}scanner=null}scanning=false}

function renderSaved(){$('#saved-list').innerHTML=state.saved.length?state.saved.map(s=>`<article class="saved-card"><div class="saved-head"><h2>${esc(s.name)}</h2><span>${Math.round(sum(s.foods).calories)} cal</span></div><p>${s.kind} · ${s.foods.length} foods</p><button class="add-btn" data-saved="${s.id}">＋ Add all to ${selectedMeal}</button></article>`).join(''):'<p class="empty">Saved meals and recipes will appear here.</p>';$$('[data-saved]').forEach(b=>b.onclick=()=>{const s=state.saved.find(x=>x.id===b.dataset.saved);if(!s)return;s.foods.forEach(f=>state.diary.push({...f,entryId:id(),meal:selectedMeal,date:selectedDate,servings:f.servings||1}));toast(`${s.name} added`);render()})}
function saveSelection(){const name=$('#saved-name').value.trim(),source=$('#saved-source').value,entries=state.diary.filter(x=>x.date===selectedDate&&(source==='all'||x.meal===source)),foods=entries.map(({entryId,meal,date,...f})=>f),kind=source==='all'?'recipe':'meal';if(!name||!foods.length)return toast('Add a name and log food in that selection first');state.saved.unshift({id:id(),name,kind,foods});$('#saved-name').value='';toast(`${kind==='meal'?'Meal':'Recipe'} saved`);render()}

function renderWeight(){const sorted=[...state.weights].sort((a,b)=>b.date.localeCompare(a.date)),latest=sorted[0]?.weight||state.profile.weight,start=sorted[sorted.length-1]?.weight||state.profile.weight,goal=state.profile.goalWeight||latest,den=Math.abs(goal-start)||1,pct=Math.min(100,Math.max(0,Math.abs(latest-start)/den*100));$('#weight-list').innerHTML=`<section class="panel"><h2>${latest} lb</h2><p class="calc-copy">Goal: ${goal} lb</p><div class="weight-progress"><i style="width:${pct}%"></i></div></section>`+(sorted.length?sorted.map(w=>`<div class="weight-row"><small>${new Date(w.date+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}</small><strong>${w.weight} lb</strong></div>`).join(''):'<p class="empty">No weights logged yet.</p>')}

function calculate(profile){const p={...profile,age:n(profile.age),feet:n(profile.feet),inches:n(profile.inches),weight:n(profile.weight),goalWeight:n(profile.goalWeight),activity:n(profile.activity),goal:n(profile.goal)};if(p.age<15||p.age>100||p.weight<70||p.weight>700||p.goalWeight<70||p.goalWeight>700||p.feet<4||p.feet>8||p.inches<0||p.inches>11||![1.2,1.375,1.55,1.725,1.9].includes(p.activity)||![-500,-250,0,125,250].includes(p.goal))throw new Error('Check age, height, weight, activity, and goal');const kg=p.weight*.453592,cm=(p.feet*12+p.inches)*2.54,bmr=10*kg+6.25*cm-5*p.age+(p.sex==='male'?5:-161),maintenance=Math.round(bmr*p.activity/10)*10,calories=Math.round((maintenance+p.goal)/10)*10,protein=Math.round(p.weight),fat=Math.round(calories*.25/9),carbs=Math.max(0,Math.round((calories-protein*4-fat*9)/4));state.profile={...p,maintenance,calculated:true,formula:'Mifflin-St Jeor estimate'};state.calorieGoal=calories;state.macros={protein,carbs,fat};return{maintenance,calories,protein,carbs,fat}}
function calculatorProfile(){return{age:$('#profile-age').value,sex:$('#profile-sex').value,feet:$('#profile-feet').value,inches:$('#profile-inches').value,weight:$('#profile-weight').value,goalWeight:state.profile.goalWeight,activity:$('#profile-activity').value,goal:$('#profile-goal').value}}
function calculateTargets(){try{calculate(calculatorProfile());toast('Targets calculated');render()}catch(e){toast(e.message)}}
function renderGoals(){const fields=[['Daily calories','calorieGoal',state.calorieGoal],['Protein (g)','protein',state.macros.protein],['Carbs (g)','carbs',state.macros.carbs],['Fat (g)','fat',state.macros.fat]];$('#goals-form').innerHTML=fields.map(([label,key,value])=>`<div class="goal-row"><label for="goal-${key}">${label}</label><input id="goal-${key}" data-goal="${key}" inputmode="numeric" value="${value}"></div>`).join('');$$('[data-goal]').forEach(i=>i.onchange=()=>{const value=Math.max(0,n(i.value));if(i.dataset.goal==='calorieGoal')state.calorieGoal=value;else state.macros[i.dataset.goal]=value;render()});const p=state.profile;$('#profile-age').value=p.age;$('#profile-sex').value=p.sex;$('#profile-feet').value=p.feet;$('#profile-inches').value=p.inches;$('#profile-weight').value=p.weight;$('#profile-activity').value=String(p.activity);$('#profile-goal').value=String(p.goal);$('#account-name').textContent=state.account.name||'Your profile';$('#account-email').textContent='Stored only on this device';const r=$('#calculation-result');r.hidden=!p.calculated;if(p.calculated)r.innerHTML=`<strong>${state.calorieGoal.toLocaleString()} calories/day</strong><span>Mifflin-St Jeor estimate · Maintenance ${p.maintenance.toLocaleString()} · Protein ${state.macros.protein}g · Carbs ${state.macros.carbs}g · Fat ${state.macros.fat}g. Adjust from your 2–3 week weight trend.</span>`}

function fillAccount(){const p=state.profile;$('#account-input-name').value=state.account.name||'';$('#account-age').value=p.age;$('#account-sex').value=p.sex;$('#account-feet').value=p.feet;$('#account-inches').value=p.inches;$('#account-weight').value=p.weight;$('#account-goal-weight').value=p.goalWeight;$('#account-activity').value=String(p.activity);$('#account-goal').value=String(p.goal);$('#account-form-title').textContent=state.account.created?'Edit your local profile':'Create your local profile';$('#account-cancel').hidden=!state.account.created}
function openAccount(){fillAccount();$('#account-dialog').showModal()}
function saveAccount(e){e.preventDefault();const profile={age:$('#account-age').value,sex:$('#account-sex').value,feet:$('#account-feet').value,inches:$('#account-inches').value,weight:$('#account-weight').value,goalWeight:$('#account-goal-weight').value,activity:$('#account-activity').value,goal:$('#account-goal').value};try{calculate(profile);state.account={created:true,name:$('#account-input-name').value.trim()};if(!state.weights.length)state.weights.push({id:id(),date:today(),weight:n(profile.weight)});$('#account-dialog').close();toast('Profile saved');render()}catch(err){toast(err.message)}}

function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`BiteLog-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup downloaded')}
async function importData(file){if(!file)return;try{const parsed=JSON.parse(await file.text());if(!parsed||!Array.isArray(parsed.diary)||!parsed.macros||!Number.isFinite(Number(parsed.calorieGoal))||Number(parsed.calorieGoal)<500||Number(parsed.calorieGoal)>10000)throw new Error();state={...seed,...parsed,account:{...seed.account,...(parsed.account||{})},profile:{...profileDefault,...(parsed.profile||{})},favorites:Array.isArray(parsed.favorites)?parsed.favorites:[],saved:Array.isArray(parsed.saved)?parsed.saved:[],weights:Array.isArray(parsed.weights)?parsed.weights:[],water:parsed.water&&typeof parsed.water==='object'?parsed.water:{}};toast('Backup restored');render()}catch{toast('That backup file is not valid')}}

$$('.nav-btn').forEach(btn=>btn.onclick=()=>showView(btn.dataset.view));$$('[data-close]').forEach(b=>b.onclick=async()=>{if(b.dataset.close==='scanner-dialog')await stopScanner();$('#'+b.dataset.close).close()});
$('#prev-day').onclick=()=>{selectedDate=shiftDate(selectedDate,-1);render()};$('#next-day').onclick=()=>{const tomorrow=shiftDate(today(),1);if(selectedDate<tomorrow)selectedDate=shiftDate(selectedDate,1);render()};$('#water-plus').onclick=()=>{state.water[selectedDate]=(state.water[selectedDate]||0)+1;render()};$('#water-minus').onclick=()=>{state.water[selectedDate]=Math.max(0,(state.water[selectedDate]||0)-1);render()};
$('#target-prompt').onclick=()=>showView('goals');$('#calculate-targets').onclick=calculateTargets;$('#edit-account').onclick=openAccount;$('#account-cancel').onclick=()=>$('#account-dialog').close();$('#account-form').onsubmit=saveAccount;
$('#search-button').onclick=searchFoods;$('#food-search').onkeydown=e=>{if(e.key==='Enter')searchFoods()};$$('[data-food-tab]').forEach(b=>b.onclick=()=>{currentFoodTab=b.dataset.foodTab;$$('[data-food-tab]').forEach(x=>x.classList.toggle('active',x===b));renderFoodList()});
$('#scan-open').onclick=openScanner;$('#manual-open').onclick=()=>{$('#add-dialog').close();$('#food-dialog').showModal()};$('#food-form').onsubmit=addManual;$('#entry-servings').oninput=updateEntryPreview;$('#entry-form').onsubmit=saveEntry;$('#delete-entry').onclick=deleteEntry;
$('#save-foods').onclick=saveSelection;$('#save-weight').onclick=()=>{const weight=n($('#weight-input').value);if(weight<70||weight>700)return toast('Enter a valid weight');state.weights=state.weights.filter(x=>x.date!==today());state.weights.push({id:id(),date:today(),weight});state.profile.weight=weight;$('#weight-input').value='';toast('Weight saved');render()};
$('#cancel-remove').onclick=()=>$('#confirm-dialog').close();$('#confirm-remove').onclick=()=>{state.diary=state.diary.filter(x=>x.entryId!==removeId);$('#confirm-dialog').close();toast('Food removed');render()};$('#export-data').onclick=exportData;$('#import-data').onchange=e=>importData(e.target.files[0]);$('#delete-all-data').onclick=()=>{if(confirm('Delete your profile, diary, saved foods, weights, and goals from this device? This cannot be undone unless you downloaded a backup.')){localStorage.removeItem('bitelog-v1');location.reload()}};
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
if(migratedGoalRate&&state.profile.calculated)calculate(state.profile);render();if(!state.account.created)setTimeout(openAccount,250);
